                AICCombatUtils.S.DebugFolder.Parent = workspace

                --// Billboard text follows the font picked in Configuration.
                if UI and UI.AddFontRoot then
                    UI:AddFontRoot(AICCombatUtils.S.DebugFolder)
                end
